# A TUPLE RATHER THAN A LIST, and that is what the error state is built on: folding an unreadable
# answer into an empty one leaves a block telling a reader that nothing is published when the truth
# is that nothing could be read.
case result do
  {:ok, %{results: found, count: count}} -> {:ok, %{rows: found, total: count || length(found)}}
  {:ok, found} when is_list(found) -> {:ok, %{rows: found, total: length(found)}}
  {:error, reason} -> {:error, reason}
  _unreadable -> {:error, :unreadable}
end

# THE VERSION IS IN THE URL ONLY WHILE IT IS NOT THE LATEST ONE. Carrying ?v=0.0.6 around a document
# whose latest version is 0.0.6 pins every link a reader shares to a number that will be old next
# week, and the same page then reads as an archived one.
key = trimmed(version_param)

case {version, latest} do
  {nil, _no_versions} -> %{}
  {_asked, nil} -> %{}
  {%{id: same}, %{id: same}} -> %{}
  {%{version_number: number}, _older} when key != "" -> %{key => to_string(number)}
  _no_key_to_write_it_under -> %{}
end

case section do
  nil ->
    {nil, nil}

  %{id: id} ->
    case Enum.find_index(sections, &(&1.id == id)) do
      nil -> {nil, nil}
      0 -> {nil, Enum.at(sections, 1)}
      found -> {Enum.at(sections, found - 1), Enum.at(sections, found + 1)}
    end
end

Enum.map(notes, fn note ->
  anchor = "note-" <> to_string(note.id)

  %{
    id: note.id,
    anchor: anchor,
    title: note.title,
    html: code_windows(placed_cards(clean(note.content), placement), labels, "#{id}-#{anchor}")
  }
end)

case socket.assigns.extras.asked == asked do
  false -> {:noreply, socket}
  true -> {:noreply, Phoenix.Component.assign(socket, :extras, unfetched(socket.assigns.extras))}
end

# WHAT NEVER ARRIVED SAYS SO: each tab still being fetched says its `failed_text`, and the header's
# skeleton is taken away.
%{
  extras
  | header: Enum.reject(extras.header, &(&1.kind == :pending)),
    tabs:
      Enum.map(extras.tabs, fn
        %{state: :not_ready} = tab -> %{tab | state: :failed, text: tab.failed_text || tab.text}
        tab -> tab
      end),
    pending: []
}

# ONE CELL, read under its column's key: a list is drawn as its items, a map with `text` as a badge
# in its tone, any other word as text — in code where the column says so — and nothing as blank.
case Map.get(row, column.key) do
  items when is_list(items) ->
    case Enum.flat_map(items, &List.wrap(plain(&1))) do
      [] -> %{kind: :blank, column: column.key}
      words -> %{kind: :items, column: column.key, items: words}
    end

  %{text: text} = badge ->
    case plain(text) do
      nil -> %{kind: :blank, column: column.key}
      word -> %{kind: :badge, column: column.key, text: word, tone: tone_of(Map.get(badge, :tone))}
    end

  value ->
    case plain(value) do
      nil -> %{kind: :blank, column: column.key}
      word -> %{kind: :text, column: column.key, text: word, code: column.code}
    end
end

# THE FACTS PLUGINS PUT UNDER THE TITLE, in the order they were given.
~H"""
<div data-role="doc-extras" class="mt-4 mb-5 flex flex-wrap items-center gap-x-5 gap-y-3">
  <.doc_extra_fact
    :for={fact <- @facts}
    fact={fact}
    row={false}
    copy_text={@copy_text}
    copied_text={@copied_text}
    copy_label={@copy_label}
  />
</div>
"""

# THE PAGE'S OWN TEXT, THEN EACH TAB A PLUGIN ADDED, each a link to the page with that tab in its
# URL. The one shown is `aria-current`.
~H"""
<nav
  data-role="doc-tabs"
  aria-label={@tabs_label}
  class="mt-5 mb-5 flex gap-1 overflow-x-auto border-b border-[#ecebe6]"
>
  <.link
    patch={@extras.docs_href}
    id={"#{@id}-tab-documentation"}
    data-role="doc-tab"
    data-tab="documentation"
    aria-current={@open == "" && "page"}
    class={[
      "-mb-px shrink-0 whitespace-nowrap border-b-2 px-4 py-2 text-sm font-semibold",
      tab_class(@open == "")
    ]}
  >
    {@docs_tab_text}
  </.link>
  <.link
    :for={tab <- @extras.tabs}
    patch={tab.href}
    id={"#{@id}-tab-#{tab.id}"}
    data-role="doc-tab"
    data-tab={tab.id}
    aria-current={@open == tab.id && "page"}
    class={[
      "-mb-px shrink-0 whitespace-nowrap border-b-2 px-4 py-2 text-sm font-semibold",
      tab_class(@open == tab.id)
    ]}
  >
    {tab.label}
  </.link>
</nav>
"""

# EACH TAB A PLUGIN ADDED, ITS PANEL: hidden unless it is the one shown; a skeleton while its data is
# being fetched, and what the plugin says when it could not be.
~H"""
<section
  :for={tab <- @tabs}
  id={"#{@id}-tab-#{tab.id}-panel"}
  data-role="doc-tab-panel"
  data-tab={tab.id}
  aria-labelledby={"#{@id}-tab-#{tab.id}"}
  hidden={@open != tab.id}
>
  <.component
    :if={tab.state == :not_ready}
    component_name="doc-notice"
    site={site_name()}
    tone="loading"
    role="doc-tab-pending"
    text={tab.text || ""}
  />

  <.component
    :if={tab.state == :failed}
    component_name="doc-notice"
    site={site_name()}
    tone="empty"
    role="doc-tab-failed"
    text={tab.text || ""}
  />

  <div
    :for={block <- tab.blocks}
    data-role={"doc-extra-" <> Atom.to_string(block.kind)}
    class="mb-8 last:mb-0"
  >
    <h2 :if={block.title} data-role="doc-extra-title" class="mb-1 text-lg font-bold leading-tight">
      {block.title}
    </h2>
    <p
      :if={block.description}
      data-role="doc-extra-description"
      dir="auto"
      class="mb-3 text-sm leading-relaxed text-[#6d6a63]"
    >
      {block.description}
    </p>

    <div
      :if={block.kind == :table and block.rows != []}
      data-role="doc-extra-table-frame"
      class="overflow-x-auto rounded-[14px] border border-[#ecebe6]"
    >
      <table data-role="doc-extra-rows" class="w-full border-collapse text-start text-sm">
        <thead class="bg-[#fbfbf9]">
          <tr>
            <th
              :for={column <- block.columns}
              scope="col"
              data-column={column.key}
              class="border-b border-[#ecebe6] px-3 py-2 text-start text-[11px] font-bold uppercase tracking-[0.08em] text-[#8a877f]"
            >
              {column.label}
            </th>
          </tr>
        </thead>
        <tbody>
          <tr
            :for={row <- block.rows}
            data-role="doc-extra-row"
            class="border-b border-[#ecebe6] last:border-b-0"
          >
            <td :for={cell <- row} data-column={cell.column} class="px-3 py-2 align-top">
              <code :if={cell.kind == :text and cell.code} dir="ltr" class="font-mono text-[13px]">{cell.text}</code>
              <span :if={cell.kind == :text and not cell.code} dir="auto">{cell.text}</span>
              <span :if={cell.kind == :items} class="flex flex-wrap gap-1">
                <code
                  :for={item <- cell.items}
                  data-role="doc-extra-item"
                  dir="ltr"
                  class="rounded bg-[#f0efea] px-1.5 py-0.5 font-mono text-xs"
                >{item}</code>
              </span>
              <span
                :if={cell.kind == :badge}
                data-role="doc-extra-badge"
                data-tone={cell.tone}
                class={[
                  "rounded-full border px-2 py-0.5 text-[11px] font-semibold",
                  badge_class(cell.tone)
                ]}
              >{cell.text}</span>
              <span :if={cell.kind == :blank} data-role="doc-extra-blank" class="text-[#b5b2aa]">—</span>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <.component
      :if={block.kind == :table and block.rows == []}
      component_name="doc-notice"
      site={site_name()}
      tone="empty"
      role="doc-extra-rows-empty"
      text={block.empty_text || ""}
    />

    <div
      :if={block.kind == :list}
      data-role="doc-extra-facts"
      class="divide-y divide-[#ecebe6] rounded-[14px] border border-[#ecebe6]"
    >
      <.doc_extra_fact
        :for={fact <- block.items}
        fact={fact}
        row={true}
        copy_text={@copy_text}
        copied_text={@copied_text}
        copy_label={@copy_label}
      />
    </div>
  </div>
</section>
"""

