// Copies a documentation code block's code when the button on its window is pressed.
//
// `doc-section` mounts this on its own root, outside the page's text, and draws every code block of
// that text in a `[data-role="doc-code"]` window with a `[data-role="doc-code-copy"]` button, and
// each command a plugin puts on the page in a `[data-role="doc-extra-command"]` with the same button.
// One listener on the root answers every button inside it, so a button a later render draws is
// answered as well as the first.
//
// The code is the text of the window's `<pre><code>` — or of its `<pre>`, or of the command's
// `<code>` — written with the Clipboard API, or through a textarea and `execCommand("copy")` where
// that API is missing or refused. Once it is copied the button carries `data-copied="true"` for
// COPIED_FOR milliseconds, for a stylesheet to draw, and the window's `[data-role="doc-code-status"]`
// reads the button's `data-copied-text` out to a screen reader. No class and no style attribute is
// written.
//
// A code window doc-section marks `data-collapsible` is cut at its `data-collapse-lines` until the
// `[data-role="doc-code-expand"]` button under its code shows all of it — the same listener answers
// it. The choice is `data-expanded` on the window and `aria-expanded` on the button, written through
// the hook's JS commands so a LiveView patch keeps them; folding a window whose top has left the
// screen brings its top back. The copy button copies the whole code either way.
const COPIED_FOR = 1200;

const BUTTON = '[data-role="doc-code-copy"]';
const WINDOW = '[data-role="doc-code"], [data-role="doc-extra-command"]';
const STATUS = '[data-role="doc-code-status"]';
const EXPAND = '[data-role="doc-code-expand"]';
const CODE = '[data-role="doc-code"]';

function copyThroughSelection(text) {
  const area = document.createElement("textarea");
  const focused = document.activeElement;
  let copied = false;

  area.value = text;
  area.setAttribute("readonly", "");
  area.setAttribute("aria-hidden", "true");
  area.style.position = "fixed";
  area.style.top = "0";
  area.style.left = "0";
  area.style.opacity = "0";
  area.style.pointerEvents = "none";
  document.body.appendChild(area);
  area.select();

  try {
    copied = document.execCommand("copy");
  } catch (_refused) {
    copied = false;
  }

  area.remove();
  if (focused && typeof focused.focus === "function") focused.focus({ preventScroll: true });

  return copied;
}

function copyText(text) {
  if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
    return navigator.clipboard.writeText(text).then(
      () => true,
      () => copyThroughSelection(text),
    );
  }

  return Promise.resolve(copyThroughSelection(text));
}

const DocCodeCopy = {
  mounted() {
    this.timers = new Map();

    this.onClick = (event) => {
      const target = event.target instanceof Element ? event.target : null;
      const button = target && target.closest(BUTTON);
      const expand = target && target.closest(EXPAND);

      if (button && this.el.contains(button)) {
        this.copy(button);
      } else if (expand && this.el.contains(expand)) {
        this.toggle(expand);
      }
    };

    this.el.addEventListener("click", this.onClick);
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    this.timers.forEach((timer) => clearTimeout(timer));
    this.timers.clear();
  },

  copy(button) {
    const frame = button.closest(WINDOW);
    const code =
      frame &&
      (frame.querySelector("pre code") || frame.querySelector("pre") || frame.querySelector("code"));
    if (!code) return;

    copyText(code.textContent).then((copied) => {
      if (copied) this.flash(button, frame);
    });
  },

  toggle(expand) {
    const frame = expand.closest(CODE);
    if (!frame) return;

    const js = this.js();

    if (frame.hasAttribute("data-expanded")) {
      js.removeAttribute(frame, "data-expanded");
      js.setAttribute(expand, "aria-expanded", "false");
      if (frame.getBoundingClientRect().top < 0) frame.scrollIntoView({ block: "start" });
    } else {
      js.setAttribute(frame, "data-expanded", "true");
      js.setAttribute(expand, "aria-expanded", "true");
    }
  },

  flash(button, frame) {
    const status = frame.querySelector(STATUS);

    clearTimeout(this.timers.get(button));
    button.setAttribute("data-copied", "true");
    if (status) status.textContent = button.getAttribute("data-copied-text") || "";

    this.timers.set(
      button,
      setTimeout(() => {
        this.timers.delete(button);
        button.removeAttribute("data-copied");
        if (status) status.textContent = "";
      }, COPIED_FOR),
    );
  },
};

export default DocCodeCopy;

// Switches a documentation example's frame between its colours, widths and directions, and keeps the
// frame as tall as the example drawn in it.
//
// `doc-example` mounts this on its own root and draws a toolbar of `[data-role="doc-example-option"]`
// buttons, each naming what it switches in `data-action` — theme, device or dir — and the choice in
// `data-value`, over a `[data-role="doc-example-frame"]` iframe. The frame's page is the example's
// HTML under the site's stylesheet: same-origin and without a script of its own, so this hook reads
// and dresses it from outside.
//
// One listener on the root answers every button. A press writes the choice onto the root as
// `data-frame-theme`, `data-frame-device` or `data-frame-dir`, and `aria-pressed` onto that
// action's buttons, through the hook's own JS commands, which a LiveView patch keeps. The frame's
// page takes the theme as `<html data-theme>` and the direction as `<html dir>`; its width is the
// stylesheet's, keyed on the root's `data-frame-device`.
//
// The frame's height is its `height` attribute — an attribute, not a style, so no CSP refuses it —
// set to its page's height when the page loads, when its fonts arrive, when the frame's width
// changes and after every choice. A link pressed inside the frame leads the page itself there,
// never the frame.
//
// An example taller than the root's `data-collapse-height` pixels is cut at that height until the
// `[data-role="doc-example-expand"]` button under it shows all of it: the hook writes
// `data-collapsible` onto the root each time it measures the frame, so a choice that changes the
// example's height decides again, and the button writes `data-expanded` onto the root and
// `aria-expanded` onto itself. Folding an example whose top has left the screen brings its top
// back. The cut and its fade are the stylesheet's, keyed on those attributes.
const OPTION = '[data-role="doc-example-option"]';
const EXPAND = '[data-role="doc-example-expand"]';
const FRAME = '[data-role="doc-example-frame"]';
const PAGE = "doc-example-page";

const CHOICES = {
  theme: ["light", "dark"],
  device: ["desktop", "tablet", "mobile"],
  dir: ["ltr", "rtl"],
};

const DocExample = {
  mounted() {
    this.dressed = new WeakSet();

    this.onClick = (event) => {
      const target = event.target instanceof Element ? event.target : null;
      const option = target && target.closest(OPTION);
      const expand = target && target.closest(EXPAND);

      if (option && this.el.contains(option)) {
        this.choose(option.getAttribute("data-action"), option.getAttribute("data-value"));
      } else if (expand && this.el.contains(expand)) {
        this.toggle(expand);
      }
    };

    this.onLoad = () => this.dress();
    this.onFollow = (event) => this.follow(event);
    this.resizes = typeof ResizeObserver === "function" ? new ResizeObserver(() => this.fit()) : null;

    this.el.addEventListener("click", this.onClick);
    this.attach();
  },

  updated() {
    this.attach();
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    this.detach();
    if (this.resizes) this.resizes.disconnect();
  },

  // The frame this root holds now, listened to; a render that drew another one hands it over.
  attach() {
    const frame = this.el.querySelector(FRAME);
    if (frame === this.frame) return;

    this.detach();
    this.frame = frame;
    if (!frame) return;

    frame.addEventListener("load", this.onLoad);
    if (this.resizes) this.resizes.observe(frame);
    this.dress();
  },

  detach() {
    if (!this.frame) return;

    this.frame.removeEventListener("load", this.onLoad);
    if (this.resizes) this.resizes.unobserve(this.frame);
    this.frame = null;
  },

  choose(action, value) {
    if (!(CHOICES[action] || []).includes(value)) return;

    const js = this.js();
    js.setAttribute(this.el, `data-frame-${action}`, value);

    this.el.querySelectorAll(`${OPTION}[data-action="${action}"]`).forEach((option) => {
      js.setAttribute(option, "aria-pressed", String(option.getAttribute("data-value") === value));
    });

    this.dress();
  },

  // The frame's page once it is the example's; until its srcdoc has loaded a frame holds an empty one.
  page() {
    const page = this.frame && this.frame.contentDocument;
    const root = page && page.documentElement;

    return root && root.getAttribute("data-role") === PAGE && page.body ? page : null;
  },

  dress() {
    const page = this.page();
    if (!page) return;

    const root = page.documentElement;
    const theme = this.el.getAttribute("data-frame-theme");
    const dir = this.el.getAttribute("data-frame-dir");

    if (CHOICES.theme.includes(theme)) root.setAttribute("data-theme", theme);
    if (CHOICES.dir.includes(dir)) root.setAttribute("dir", dir);

    if (!this.dressed.has(page)) {
      this.dressed.add(page);
      page.addEventListener("click", this.onFollow);
      if (page.fonts) page.fonts.ready.then(() => this.fit());
    }

    this.fit();
  },

  fit() {
    const page = this.page();
    if (!page) return;

    const height = Math.ceil(
      Math.max(page.documentElement.getBoundingClientRect().height, page.body.scrollHeight),
    );

    if (height > 0 && this.frame.getAttribute("height") !== String(height)) {
      this.js().setAttribute(this.frame, "height", String(height));
    }

    if (height > 0) this.collapse(height);
  },

  collapse(height) {
    const limit = Number(this.el.getAttribute("data-collapse-height")) || 0;
    const collapsible = limit > 0 && height > limit;
    if (collapsible === this.el.hasAttribute("data-collapsible")) return;

    if (collapsible) {
      this.js().setAttribute(this.el, "data-collapsible", "true");
    } else {
      this.js().removeAttribute(this.el, "data-collapsible");
    }
  },

  toggle(expand) {
    const js = this.js();

    if (this.el.hasAttribute("data-expanded")) {
      js.removeAttribute(this.el, "data-expanded");
      js.setAttribute(expand, "aria-expanded", "false");
      if (this.el.getBoundingClientRect().top < 0) this.el.scrollIntoView({ block: "start" });
    } else {
      js.setAttribute(this.el, "data-expanded", "true");
      js.setAttribute(expand, "aria-expanded", "true");
    }
  },

  follow(event) {
    const target = event.target;
    const link = target && typeof target.closest === "function" ? target.closest("a[href]") : null;
    if (!link || event.defaultPrevented) return;

    event.preventDefault();
    const url = new URL(link.getAttribute("href"), window.location.href);

    if (link.getAttribute("target") === "_blank") {
      window.open(url.href, "_blank", "noopener");
    } else if (url.origin === window.location.origin) {
      this.js().navigate(url.pathname + url.search + url.hash);
    } else {
      window.location.assign(url.href);
    }
  },
};

export default DocExample;

stylesheets.content:
/* Code in a documentation page: <pre class="highlight"><code class="language-x"> with one <span>
   per token. The token classes are the ones Makeup emits, coloured in its Monokai style. */
pre.highlight {
  color: #f8f8f2;
  background-color: #272822;
  border-radius: 12px;
  padding: 16px 20px;
  margin: 0 0 12px;
  overflow-x: auto;
  font-size: 13px;
  line-height: 1.6;
  direction: ltr;
  text-align: left;
  tab-size: 2;
}

pre.highlight code {
  display: block;
  padding: 0;
  background: transparent;
  color: inherit;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: inherit;
  white-space: pre;
}

/* The window doc-section draws each code block in: a head holding the block's language and a button
   that copies its code, over the block. The button carries data-copied for a moment once the code
   is copied; doc-code-status is what a screen reader is told. */
[data-role="doc-code"] {
  margin: 0 0 12px;
  border-radius: 12px;
  background-color: #272822;
  overflow: hidden;
  direction: ltr;
  text-align: left;
}

[data-role="doc-code"] > pre {
  margin: 0;
  border-radius: 0;
}

[data-role="doc-code-head"] {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 8px 20px;
  border-bottom: 1px solid rgba(248, 248, 242, 0.1);
  color: #a59f85;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
}

[data-role="doc-code-lang"] {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-role="doc-code-copy"] {
  display: inline-flex;
  align-items: center;
  margin-left: auto;
  padding: 2px 10px;
  border: 1px solid rgba(248, 248, 242, 0.2);
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

[data-role="doc-code-copy"]:hover {
  border-color: rgba(248, 248, 242, 0.45);
  color: #f8f8f2;
}

[data-role="doc-code-copy"]:focus-visible {
  outline: 2px solid #66d9ef;
  outline-offset: 2px;
}

[data-role="doc-code-copied-text"] {
  display: none;
  align-items: center;
  gap: 0.4em;
}

[data-role="doc-code-copy"][data-copied] {
  border-color: #a6e22e;
  color: #a6e22e;
}

[data-role="doc-code-copy"][data-copied] [data-role="doc-code-copy-text"] {
  display: none;
}

[data-role="doc-code-copy"][data-copied] [data-role="doc-code-copied-text"] {
  display: inline-flex;
}

[data-role="doc-code-status"] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* A long code block, and a tall example, cut at their data-collapse-lines and data-collapse-height
   until the button under them shows all of it: the cut lines fade out under a light blur, with the
   button on the fade. data-expanded draws it whole, the button under it. */
[data-role="doc-code"][data-collapsible] {
  position: relative;
}

[data-role="doc-code"][data-collapsible]:not([data-expanded]) > pre {
  overflow-y: hidden;
}

[data-role="doc-code"][data-collapse-lines="8"]:not([data-expanded]) > pre { max-height: calc(8lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="12"]:not([data-expanded]) > pre { max-height: calc(12lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="16"]:not([data-expanded]) > pre { max-height: calc(16lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="20"]:not([data-expanded]) > pre { max-height: calc(20lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="24"]:not([data-expanded]) > pre { max-height: calc(24lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="32"]:not([data-expanded]) > pre { max-height: calc(32lh + 1.25em); }

[data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] {
  overflow-y: hidden;
}

[data-role="doc-example"][data-collapse-height="240"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 240px; }
[data-role="doc-example"][data-collapse-height="320"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 320px; }
[data-role="doc-example"][data-collapse-height="400"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 400px; }
[data-role="doc-example"][data-collapse-height="480"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 480px; }
[data-role="doc-example"][data-collapse-height="640"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 640px; }

[data-role="doc-code-foot"],
[data-role="doc-example-foot"] {
  display: flex;
  justify-content: center;
  padding: 8px 12px 12px;
}

[data-role="doc-example"]:not([data-collapsible]) [data-role="doc-example-foot"] {
  display: none;
}

[data-role="doc-code"][data-collapsible]:not([data-expanded]) > [data-role="doc-code-foot"],
[data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding-top: 64px;
  background: linear-gradient(to bottom, rgba(39, 40, 34, 0), #272822 70%);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 40%);
  mask-image: linear-gradient(to bottom, transparent, #000 40%);
}

[data-role="doc-example"][data-frame-theme="light"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0), #ffffff 70%);
}

[data-role="doc-example"][data-frame-theme="dark"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  background: linear-gradient(to bottom, rgba(24, 23, 28, 0), #18171c 70%);
}

[data-role="doc-code-expand"] {
  padding: 3px 12px;
  border: 1px solid rgba(248, 248, 242, 0.2);
  border-radius: 9999px;
  background: #272822;
  color: #a59f85;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}

[data-role="doc-code-expand"]:hover {
  border-color: rgba(248, 248, 242, 0.45);
  color: #f8f8f2;
}

[data-role="doc-code-expand"]:focus-visible,
[data-role="doc-example-expand"]:focus-visible {
  outline: 2px solid #66d9ef;
  outline-offset: 2px;
}

[data-role="doc-code-collapse-text"],
[data-role="doc-example-collapse-text"] {
  display: none;
}

[data-role="doc-code"][data-expanded] [data-role="doc-code-expand-text"],
[data-role="doc-example"][data-expanded] [data-role="doc-example-expand-text"] {
  display: none;
}

[data-role="doc-code"][data-expanded] [data-role="doc-code-collapse-text"],
[data-role="doc-example"][data-expanded] [data-role="doc-example-collapse-text"] {
  display: inline;
}

